"""Decode the JSON inside /soccer/field_info's std_msgs/String.data."""

from __future__ import annotations

import json
import math
from dataclasses import fields

from .types import FieldDimensions


def field_dimensions_from_json(data: str) -> FieldDimensions:
    try:
        payload = json.loads(data)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid field info JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise ValueError("field info JSON must be an object")
    version = payload.get("schema_version")
    if type(version) is not int or version != 1:
        raise ValueError("field info schema_version must be 1")
    dimensions = payload.get("dimensions")
    if not isinstance(dimensions, dict):
        raise ValueError("field info dimensions must be an object")

    values = {}
    for item in fields(FieldDimensions):
        value = dimensions.get(item.name)
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(f"dimensions.{item.name} must be a number")
        try:
            number = float(value)
        except OverflowError as exc:
            raise ValueError(f"dimensions.{item.name} is too large") from exc
        if not math.isfinite(number) or number <= 0.0:
            raise ValueError(f"dimensions.{item.name} must be finite and positive")
        values[item.name] = number
    return FieldDimensions(**values)

src/framework/game_codec.py:
"""Decode GameController state from JSON.

Convert JSON from the GameController topic into :class:`GameControlState`.
This module only maps and validates fields, has no ROS or SDK dependencies,
and can be tested independently on a development machine.

Only decoding is retained because the new framework does not need encoding.
"""

from __future__ import annotations

import json
from collections.abc import Mapping

from .types import (
    KICKING_TEAM_NONE,
    CompetitionType,
    GameControlState,
    GamePhase,
    GameState,
    Penalty,
    PlayerState,
    SetPlay,
    TeamState,
)


__all__ = [
    "game_control_state_from_dict",
    "game_control_state_from_json",
]


def game_control_state_from_json(data: str) -> GameControlState:
    try:
        payload = json.loads(data)
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid GameControlState JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise ValueError("GameControlState JSON must be an object")
    return game_control_state_from_dict(payload)


def game_control_state_from_dict(payload: Mapping[str, object]) -> GameControlState:
    teams_payload = payload.get("teams", [])
    if not isinstance(teams_payload, list):
        raise ValueError("GameControlState.teams must be a list")
    return GameControlState(
        packet_number=_json_int(payload, "packetNumber", 0),
        players_per_team=_json_int(payload, "playersPerTeam", 0),
        competition_type=CompetitionType(
            _json_str(payload, "competitionType", CompetitionType.MIDDLE.value)
        ),
        stopped=_json_bool(payload, "stopped", False),
        game_phase=GamePhase(_json_str(payload, "gamePhase", GamePhase.NORMAL.value)),
        state=GameState(_json_str(payload, "state", GameState.INITIAL.value)),
        set_play=SetPlay(_json_str(payload, "setPlay", SetPlay.NONE.value)),
        first_half=_json_bool(payload, "firstHalf", True),
        kicking_team=_json_int(payload, "kickingTeam", KICKING_TEAM_NONE),
        secs_remaining=_json_int(payload, "secsRemaining", 0),
        secondary_time=_json_int(payload, "secondaryTime", 0),
        teams=tuple(team_state_from_dict(team) for team in teams_payload),
    )


def team_state_from_dict(payload: object) -> TeamState:
    if not isinstance(payload, Mapping):
        raise ValueError("TeamState JSON item must be an object")
    players_payload = payload.get("players", [])
    if not isinstance(players_payload, list):
        raise ValueError("TeamState.players must be a list")
    return TeamState(
        team_number=_json_int(payload, "teamNumber", 1),
        field_player_colour=_json_int(payload, "fieldPlayerColour", 0),
        goalkeeper_colour=_json_int(payload, "goalkeeperColour", 0),
        goalkeeper=_json_int(payload, "goalkeeper", 0),
        score=_json_int(payload, "score", 0),
        penalty_shot=_json_int(payload, "penaltyShot", 0),
        single_shots=_json_int(payload, "singleShots", 0),
        message_budget=_json_int(payload, "messageBudget", 0),
        players=tuple(player_state_from_dict(player) for player in players_payload),
    )


def player_state_from_dict(payload: object) -> PlayerState:
    if not isinstance(payload, Mapping):
        raise ValueError("PlayerState JSON item must be an object")
    return PlayerState(
        penalty=Penalty(_json_str(payload, "penalty", Penalty.NONE.value)),
        secs_till_unpenalised=_json_int(payload, "secsTillUnpenalised", 0),
        warnings=_json_int(payload, "warnings", 0),
        cautions=_json_int(payload, "cautions", 0),
    )


def _json_int(payload: Mapping[str, object], key: str, default: int) -> int:
    value = payload.get(key, default)
    if isinstance(value, (int, float, str)):
        return int(value)
    raise ValueError(f"{key} must be an int-compatible value")


def _json_str(payload: Mapping[str, object], key: str, default: str) -> str:
    value = payload.get(key, default)
    if isinstance(value, (str, int, float, bool)):
        return str(value)
    raise ValueError(f"{key} must be a string-compatible value")


def _json_bool(payload: Mapping[str, object], key: str, default: bool) -> bool:
    value = payload.get(key, default)
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value != 0
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"1", "true", "yes", "y", "on"}:
            return True
        if normalized in {"0", "false", "no", "n", "off"}:
            return False
    raise ValueError(f"{key} must be a bool-compatible value")

src/framework/ros_source.py:
"""ROS ground-truth source providing WorldSnapshot from simulation topics.

This Docker-only platform layer depends on rclpy, geometry_msgs, and std_msgs
and is imported only in a ROS environment. The runtime, player, and types logic
does not import it directly; ContextSource injection keeps runtime testable on
development machines without ROS.

Subscriptions use team-relative coordinates transformed by the simulator:
- teammate pose: /team{id}/{robot_name}/soccer/sim/ground_truth/robot_pose
- opponent pose: the same pattern using opponent_robot_names
- ball: /team{id}/soccer/sim/ground_truth/ball
- GameController: game_controller_topic as std_msgs/String JSON
- field dimensions: /soccer/field_info as retained std_msgs/String JSON

The node, SingleThreadedExecutor, and spin-thread lifecycle were ported from the
legacy SoccerRosAdapter.
"""

from __future__ import annotations

import logging
import threading
import time
from typing import Any

import rclpy
from geometry_msgs.msg import Pose2D as RosPose2D
from rclpy.executors import ExternalShutdownException, SingleThreadedExecutor
from rclpy.qos import (
    QoSDurabilityPolicy,
    QoSHistoryPolicy,
    QoSProfile,
    QoSReliabilityPolicy,
)
from std_msgs.msg import String as RosString

from .config import SoccerConfig
from .field_codec import field_dimensions_from_json
from .game_codec import game_control_state_from_json
from .types import (
    BallState, FieldDimensions, GameControlState, Pose2D, RobotState, WorldSnapshot,
)


__all__ = ["RosContextSource"]


_log = logging.getLogger(__name__)


class RosContextSource:
    """Own ROS subscriptions and aggregate current ground truth into snapshots.

    This implements runtime's ContextSource protocol: ``start``, ``stop``, and
    ``get_snapshot``. All stored objects are immutable frozen dataclasses, so
    ``get_snapshot`` only needs shallow dictionary copies.
    """

    def __init__(self, config: SoccerConfig) -> None:
        self._config = config
        self._lock = threading.RLock()
        self._subscriptions: list[Any] = []

        self._teammates: dict[int, RobotState] = {
            pid: RobotState(player_id=pid) for pid in config.player_ids
        }
        self._opponents: dict[int, RobotState] = {
            pid: RobotState(player_id=pid)
            for pid in range(1, len(config.opponent_robot_names) + 1)
        }
        self._ball: BallState | None = None
        self._game: GameControlState | None = None
        self._field: FieldDimensions | None = None

        # ROS node and executor lifecycle.
        self._owns_context = False
        self._ros_context: Any = None
        self._node: Any = None
        self._executor: SingleThreadedExecutor | None = None
        self._spin_thread: threading.Thread | None = None
        self._started = False

    # ------------------------------------------------------------------
    # ContextSource protocol
    # ------------------------------------------------------------------

    def start(self) -> None:
        if self._started:
            return
        self._started = True
        self._node = self._create_node()
        self._create_subscriptions()
        # Reuse this node for Docker-only debug markers and Python logs.
        from . import debugdraw
        from . import log_publisher
        debugdraw.install(self._node)
        log_publisher.install(self._node)
        self._start_spin()
        _log.info(
            "RosContextSource started: team_id=%d gc_topic=%s",
            self._config.team_id, self._config.game_controller_topic,
        )

    def stop(self) -> None:
        if not self._started:
            return
        self._started = False
        self._stop_spin()
        self._destroy_node()

    def get_snapshot(self) -> WorldSnapshot:
        with self._lock:
            return WorldSnapshot(
                game=self._game,
                ball=self._ball,
                teammates=dict(self._teammates),
                opponents=dict(self._opponents),
                field=self._field,
            )

    # ------------------------------------------------------------------
    # Subscriptions
    # ------------------------------------------------------------------

    def _create_subscriptions(self) -> None:
        self._subscriptions.append(
            self._node.create_subscription(
                RosString,
                "/soccer/field_info",
                self._field_cb,
                QoSProfile(
                    history=QoSHistoryPolicy.KEEP_LAST,
                    depth=1,
                    durability=QoSDurabilityPolicy.TRANSIENT_LOCAL,
                    reliability=QoSReliabilityPolicy.RELIABLE,
                ),
            )
        )
        truth_qos = self._qos(depth=1)
        for pid, name in enumerate(self._config.robot_names, start=1):
            self._subscriptions.append(
                self._node.create_subscription(
                    RosPose2D,
                    self._robot_topic(name, "soccer/sim/ground_truth/robot_pose"),
                    self._make_pose_cb(self._teammates, pid),
                    truth_qos,
                )
            )
        for pid, name in enumerate(self._config.opponent_robot_names, start=1):
            self._subscriptions.append(
                self._node.create_subscription(
                    RosPose2D,
                    self._robot_topic(name, "soccer/sim/ground_truth/robot_pose"),
                    self._make_pose_cb(self._opponents, pid),
                    truth_qos,
                )
            )
        self._subscriptions.append(
            self._node.create_subscription(
                RosPose2D,
                self._team_topic("soccer/sim/ground_truth/ball"),
                self._ball_cb,
                truth_qos,
            )
        )
        self._subscriptions.append(
            self._node.create_subscription(
                RosString,
                self._config.game_controller_topic,
                self._game_cb,
                self._qos(depth=10),
            )
        )

    def _field_cb(self, msg: Any) -> None:
        try:
            dimensions = field_dimensions_from_json(str(msg.data))
        except ValueError as exc:
            _log.warning("ignore invalid field info payload: %s", exc)
            return
        with self._lock:
            self._field = dimensions
        _log.info("field info received from /soccer/field_info: %s", dimensions)

    def _make_pose_cb(self, store: dict[int, RobotState], player_id: int):
        def callback(msg: Any) -> None:
            pose = Pose2D(x=float(msg.x), y=float(msg.y), theta=float(msg.theta))
            with self._lock:
                store[player_id] = RobotState(
                    player_id=player_id,
                    pose=pose,
                    last_seen_at=time.monotonic(),
                )
        return callback

    def _ball_cb(self, msg: Any) -> None:
        ball = BallState(
            x=float(msg.x),
            y=float(msg.y),
            last_seen_at=time.monotonic(),
            confidence=1.0,
        )
        with self._lock:
            self._ball = ball

    def _game_cb(self, msg: Any) -> None:
        try:
            game = game_control_state_from_json(str(msg.data))
        except ValueError as exc:
            _log.warning("ignore invalid GameController payload: %s", exc)
            return
        # Use replace to stamp last_seen_at on the frozen dataclass.
        import dataclasses
        game = dataclasses.replace(game, last_seen_at=time.monotonic())
        with self._lock:
            self._game = game

    # ------------------------------------------------------------------
    # Topic names
    # ------------------------------------------------------------------

    def _robot_topic(self, robot_name: str, suffix: str) -> str:
        if robot_name:
            return self._join(f"team{self._config.team_id}", robot_name, suffix)
        return self._team_topic(suffix)

    def _team_topic(self, suffix: str) -> str:
        return self._join(f"team{self._config.team_id}", suffix)

    @staticmethod
    def _join(*parts: str) -> str:
        clean = [p.strip("/") for p in parts if p.strip("/")]
        return "/" + "/".join(clean)

    def _qos(self, depth: int) -> QoSProfile:
        return QoSProfile(
            history=QoSHistoryPolicy.KEEP_LAST,
            depth=depth,
            durability=QoSDurabilityPolicy.VOLATILE,
            reliability=QoSReliabilityPolicy.RELIABLE,
        )

    # ------------------------------------------------------------------
    # Node and executor lifecycle, ported from the legacy SoccerRosAdapter
    # ------------------------------------------------------------------

    def _create_node(self) -> Any:
        context = rclpy.get_default_context()
        self._ros_context = context
        if not rclpy.ok(context=context):
            context.init(args=None, initialize_logging=False)
            self._owns_context = True
        return rclpy.create_node("soccer_sim_bridge", context=context)

    def _start_spin(self) -> None:
        self._executor = SingleThreadedExecutor(context=self._ros_context)
        self._executor.add_node(self._node)
        self._spin_thread = threading.Thread(
            target=self._spin, name="soccer_ros_source_spin", daemon=True,
        )
        self._spin_thread.start()

    def _spin(self) -> None:
        if self._executor is None:
            return
        try:
            self._executor.spin()
        except ExternalShutdownException:
            pass
        except Exception as exc:
            _log.warning("RosContextSource spin failed: %s", exc)

    def _stop_spin(self) -> None:
        if self._executor is not None:
            try:
                self._executor.shutdown()
            except Exception as exc:
                _log.warning("executor shutdown failed: %s", exc)
        if self._spin_thread is not None and self._spin_thread.is_alive():
            self._spin_thread.join(timeout=2.0)
        self._spin_thread = None
        self._executor = None

    def _destroy_node(self) -> None:
        for sub in self._subscriptions:
            try:
                self._node.destroy_subscription(sub)
            except Exception:
                pass
        self._subscriptions.clear()
        if self._node is not None:
            try:
                self._node.destroy_node()
            except Exception as exc:
                _log.warning("node destroy failed: %s", exc)
        if (
            self._owns_context
            and self._ros_context is not None
            and rclpy.ok(context=self._ros_context)
        ):
            self._ros_context.shutdown()
        self._node = None

