"""Roamer-only target geometry; baseline approach and keeper are unchanged."""
import math

from .param import SHOT_RANGE_M, SHOT_POWER, DRIVE_POWER, SHOT_POST_MARGIN_M, SHOT_GOAL_DEPTH_M, RETREAT_FIELD_MARGIN_M
from .roamer_params import (
    LANE_RADIUS_M, LANE_KEEP_MARGIN_M, DRIBBLE_FORWARD_M, DRIBBLE_SIDE_M,
    DRIBBLE_FIELD_MARGIN_M, NATIVE_GOAL_DISTANCE_M, ESCAPE_RADIUS_M,
    SAFE_PATH_RADIUS_M, ESCAPE_STEP_M, ESCAPE_SAMPLES, DRIBBLE_KEEP_MIN_M,
    DRIBBLE_KEEP_MAX_M, DRIBBLE_BACKSTEP_MARGIN_M,
)
from .tactics import retreat_target


def segment_distance(point, start, end):
    dx, dy = end[0]-start[0], end[1]-start[1]
    length2 = dx*dx+dy*dy
    t = 0 if length2 == 0 else max(0,min(1,((point[0]-start[0])*dx+(point[1]-start[1])*dy)/length2))
    return math.dist(point,(start[0]+t*dx,start[1]+t*dy))


def lane_clearance(ball, target, opponents):
    return min((segment_distance((r.pose.x,r.pose.y),ball,target) for r in opponents.values() if r.pose is not None),default=math.inf)


def shooting_plan(field, ball, opponents, previous=None):
    if ball is None or not all(math.isfinite(v) for v in ball):
        return None, None
    goal_x = field.length/2+SHOT_GOAL_DEPTH_M
    limit = field.goal_width/2-SHOT_POST_MARGIN_M
    goals = [(goal_x,y) for y in (0,-limit,limit,-limit/2,limit/2)]
    score = lambda target: min(1.0,lane_clearance(ball,target,opponents))
    target = max(goals,key=lambda p:(score(p),-abs(p[1])))
    if previous in goals and score(previous)>=score(target)-LANE_KEEP_MARGIN_M:
        target = previous
    in_range = math.dist(ball,(field.length/2,0))<=SHOT_RANGE_M
    if not in_range or score(target)>=LANE_RADIUS_M:
        return target, SHOT_POWER if in_range else DRIVE_POWER
    def clamp(x,y):
        return (max(-field.length/2+DRIBBLE_FIELD_MARGIN_M,min(field.length/2-DRIBBLE_FIELD_MARGIN_M,x)),
                max(-field.width/2+DRIBBLE_FIELD_MARGIN_M,min(field.width/2-DRIBBLE_FIELD_MARGIN_M,y)))
    options = [clamp(ball[0]+DRIBBLE_FORWARD_M,ball[1]+side*DRIBBLE_SIDE_M) for side in (-1,0,1)]
    target = max(options,key=lambda p:(score(p),-abs(p[1])))
    if previous is not None and previous not in goals and DRIBBLE_KEEP_MIN_M<math.dist(ball,previous)<DRIBBLE_KEEP_MAX_M and previous[0]>=ball[0]-DRIBBLE_BACKSTEP_MARGIN_M and score(previous)>=score(target)-LANE_KEEP_MARGIN_M:
        target = previous
    return target, DRIVE_POWER


def native_aim_target(pose, ball, target):
    if pose is None or ball is None or target is None:
        return target
    length = math.dist(ball,target)
    if length < 1e-6:
        return target
    ux,uy = (target[0]-ball[0])/length,(target[1]-ball[1])/length
    ox,oy = ball[0]-pose.x,ball[1]-pose.y
    perpendicular = ox*uy-oy*ux
    if abs(perpendicular)>=NATIVE_GOAL_DISTANCE_M:
        return target
    travel = -(ox*ux+oy*uy)+math.sqrt(NATIVE_GOAL_DISTANCE_M**2-perpendicular**2)
    vx,vy = ox+travel*ux,oy+travel*uy
    return ball[0]+vx,ball[1]+vy


def roamer_retreat_target(field, position, ball):
    far = retreat_target(field,position,ball)
    if far is None or ball is None:
        return None
    radius = math.dist(position,ball)
    half_l,half_w = field.length/2-RETREAT_FIELD_MARGIN_M,field.width/2-RETREAT_FIELD_MARGIN_M
    def inside(p):return abs(p[0])<=half_l and abs(p[1])<=half_w
    if radius < ESCAPE_RADIUS_M:
        points = [(ball[0]+ESCAPE_RADIUS_M*math.cos(i*math.tau/ESCAPE_SAMPLES),ball[1]+ESCAPE_RADIUS_M*math.sin(i*math.tau/ESCAPE_SAMPLES)) for i in range(ESCAPE_SAMPLES)]
        points = [p for p in points if inside(p)]
        return min(points,key=lambda p:math.dist(position,p)) if points else far
    if segment_distance(ball,position,far)>=SAFE_PATH_RADIUS_M:
        return far
    angle = math.atan2(position[1]-ball[1],position[0]-ball[0])
    delta = ESCAPE_STEP_M/max(radius,ESCAPE_RADIUS_M)
    points = [(ball[0]+radius*math.cos(angle+sign*delta),ball[1]+radius*math.sin(angle+sign*delta)) for sign in (-1,1)]
    points = [p for p in points if inside(p)]
    return min(points,key=lambda p:math.dist(p,far)) if points else far

